"""Regenerate the synthetic panel fixtures in this directory.

Run ``python3 benchmark/tests/fixtures/panels/synthetic/regenerate.py`` after
editing a project below. It rebuilds each upstream with pinned commit metadata
and writes ``projects.json`` plus ``rows.json``: one Go and one Rust SWE-bench
Multilingual row under the panel's Go and Rust slot ids, and one FeatureBench
Level 1 row. Each instance has one FAIL_TO_PASS and one PASS_TO_PASS test
written for the fixture, so the real prepare and grading hooks run natively on
the host ``go``, ``cargo``, and Python. Nothing here comes from a real dataset row.
"""

import json
import shutil
import sys
import tempfile
from pathlib import Path

HERE = Path(__file__).parent
sys.path.insert(0, str(HERE.parents[2]))

from external_support import build_upstream, git, write_tree  # noqa: E402

GO_SLOT = "gin-gonic__gin-3741"
RUST_SLOT = "sharkdp__bat-2650"
FEATUREBENCH_ID = "fixture__panelpy.00000000.test_total.00000000.lv1"

GO_SRC = '''package panelgo

// Max returns the larger value.
func Max(a, b int) int {
\tif a > b {
\t\treturn a
\t}
\treturn b
}

// Sum adds every value.
func Sum(values []int) int {
\ttotal := 0
\tfor range values {
\t\ttotal++
\t}
\treturn total
}
'''

GO_TEST = '''package panelgo

import "testing"

func TestMax(t *testing.T) {
\tif Max(2, 3) != 3 {
\t\tt.Fatal("max")
\t}
}
'''

RS_SRC = '''pub fn max(a: i64, b: i64) -> i64 {
    if a > b { a } else { b }
}

pub fn sum(values: &[i64]) -> i64 {
    values.len() as i64
}
'''

RS_TEST = '''use panelrs::max;

#[test]
fn max_works() {
    assert_eq!(max(2, 3), 3);
}
'''

PY_CORE = '''"""Number helpers."""


def biggest(values):
    """Return the largest value."""
    return max(values)


def total(values):
    """Return the sum of the values."""
    return sum(values)
'''

PY_CORE_MASKED = '''"""Number helpers."""


def biggest(values):
    """Return the largest value."""
    return max(values)
'''

PY_TOTAL_TEST = '''from panelpy.core import total


def test_total():
    assert total([1, 2, 3]) == 6
'''

PY_BIGGEST_TEST = '''from panelpy.core import biggest


def test_biggest():
    assert biggest([1, 5, 3]) == 5
'''

PROJECTS = {
    "fixture/panelgo": {"go.mod": "module example.com/panelgo\n\ngo 1.21\n", "panel.go": GO_SRC, "panel_test.go": GO_TEST},
    "fixture/panelrs": {
        "Cargo.toml": '[package]\nname = "panelrs"\nversion = "0.1.0"\nedition = "2021"\n\n[dependencies]\n',
        "Cargo.lock": "# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\n"
                      'version = 3\n\n[[package]]\nname = "panelrs"\nversion = "0.1.0"\n',
        "src/lib.rs": RS_SRC,
        "tests/panel.rs": RS_TEST,
    },
    "fixture/panelpy": {
        "panelpy/__init__.py": '"""Panel fixture package."""\n',
        "panelpy/core.py": PY_CORE,
        "tests/test_total.py": PY_TOTAL_TEST,
        "tests/test_biggest.py": PY_BIGGEST_TEST,
    },
}

SWE = {
    "fixture/panelgo": {
        "instance_id": GO_SLOT, "log_parser": "parse_log_gotest",
        "fix": {"panel.go": GO_SRC.replace("for range values {\n\t\ttotal++", "for _, value := range values {\n\t\ttotal += value")},
        "tests": {"panel_test.go": GO_TEST + "\nfunc TestSum(t *testing.T) {\n\tif Sum([]int{1, 2, 3}) != 6 {\n\t\tt.Fatal(\"sum\")\n\t}\n}\n"},
        "command": '(go test -v . -run "^Test") | cat',
        "f2p": ["TestSum"], "p2p": ["TestMax"],
    },
    "fixture/panelrs": {
        "instance_id": RUST_SLOT, "log_parser": "parse_log_cargo",
        "fix": {"src/lib.rs": RS_SRC.replace("values.len() as i64", "values.iter().sum()")},
        "tests": {"tests/panel.rs": RS_TEST.replace("use panelrs::max;", "use panelrs::{max, sum};")
                  + "\n#[test]\nfn sum_works() {\n    assert_eq!(sum(&[1, 2, 3]), 6);\n}\n"},
        "command": "(RUSTFLAGS=-Awarnings cargo test --test panel) | cat",
        "f2p": ["sum_works"], "p2p": ["max_works"],
    },
}

EVAL_SCRIPT = """#!/bin/bash
set -uxo pipefail
cd /testbed
git checkout {base} {test_files}
git apply -v - <<'EOF_PANEL'
{test_patch}
EOF_PANEL
: '>>>>> Start Test Output'
{command}
: '>>>>> End Test Output'
git checkout {base} {test_files}
"""

REPO_SETTINGS = {
    "repository": "fixture/panelpy", "commit": "", "base_image": "python311", "pre_install": [], "install": "",
    "pip_packages": [], "test_cmd": "pytest -rA --tb=short --color=no", "library_name": "panelpy",
}


def diff(work: Path, files: dict[str, str | None]) -> str:
    """Return the git diff that turns the checked-out base into ``files`` (None deletes)."""
    for relative, content in files.items():
        if content is None:
            (work / relative).unlink()
        else:
            write_tree(work, {relative: content})
    patch = git("diff", "--no-color", "HEAD", cwd=work)
    git("reset", "-q", "--hard", "HEAD", cwd=work)
    git("clean", "-qfd", cwd=work)
    return patch


def main() -> None:
    rows = []
    with tempfile.TemporaryDirectory() as temp:
        root = Path(temp)
        for repo, files in PROJECTS.items():
            bare, base = build_upstream(repo, files, root / "upstream")
            work = root / "checkout" / repo
            git("clone", "-q", str(bare), str(work), cwd=root)
            if repo in SWE:
                spec = SWE[repo]
                test_patch = diff(work, spec["tests"])
                rows.append({
                    "base_commit": base, "created_at": "2026-01-01 00:00:00", "eval_type": "pass_and_fail",
                    "image": "synthetic", "instance_id": spec["instance_id"], "log_parser": spec["log_parser"],
                    "repo": repo, "version": "0", "patch": diff(work, spec["fix"]), "test_patch": test_patch,
                    "eval_script": EVAL_SCRIPT.format(base=base, test_files=" ".join(spec["tests"]),
                                                      test_patch=test_patch.rstrip("\n"), command=spec["command"]),
                    "problem_statement": f"{repo}: sum returns the count, not the total.\n", "hints_text": "",
                    "FAIL_TO_PASS": spec["f2p"], "PASS_TO_PASS": spec["p2p"],
                })
            else:
                mask = diff(work, {"panelpy/core.py": PY_CORE_MASKED})
                rows.append({
                    "instance_id": FEATUREBENCH_ID, "patch": mask,
                    "test_patch": diff(work, {"tests/test_total.py": None}),
                    "FAIL_TO_PASS": ["tests/test_total.py"], "PASS_TO_PASS": ["tests/test_biggest.py"],
                    "image_name": "synthetic", "repo": repo, "base_commit": base,
                    "problem_statement": "Implement ``total`` in ``panelpy.core``: return the sum of the values.\n",
                    "repo_settings": json.dumps({**REPO_SETTINGS, "commit": base[:7]}),
                })
            shutil.rmtree(work)
    (HERE / "projects.json").write_text(json.dumps(PROJECTS, indent=1) + "\n")
    (HERE / "rows.json").write_text(json.dumps(rows, indent=1) + "\n")


if __name__ == "__main__":
    main()
